const L=[`Hereda+ · informe · motor ${VERSION}`,`${x.nombre||"Herencia"} · ${nombreTerr(x.ccaa)} · fallecimiento ${x.fecha}`,`Caudal del fallecido ${eur(R.isd.masa.bruto)} · neto ${eur(R.isd.masa.neto)} · ajuar ${eur(R.isd.masa.ajuar)}`,""];
