let E=null;try{E=R?estrategia(x):null;}catch(e){E=null;}
const sim=(fn)=>{try{const y=JSON.parse(JSON.stringify(x));fn(y);const Ry=calcular(y);return Ry?Ry.isd.total+Ry.totalPlus:null;}catch(e){return null;}};
