if(!x.ccaa)add({id:"sin-terr",area:"datos",tipo:"dato",gravedad:3,titulo:"Falta la comunidad autónoma",detalle:"La residencia fiscal del fallecido decide qué normativa de Sucesiones se aplica y cuánto se paga.",accion:"Indica dónde residió los últimos cinco años.",norma:"art. 32 Ley 22/2009",enlace:{act:"editar"}});
if(!pers.length)add({id:"sin-personas",area:"datos",tipo:"dato",gravedad:3,titulo:"No hay herederos",detalle:"Sin herederos no hay reparto ni impuesto que calcular.",accion:"Añade al menos una persona.",enlace:{sec:"herencia"}});
if(!bienes.length)add({id:"sin-bienes",area:"datos",tipo:"dato",gravedad:3,titulo:"No hay bienes",detalle:"El inventario está vacío: no se puede formar la masa hereditaria.",accion:"Añade los bienes del fallecido, aunque sea con valores aproximados.",enlace:{sec:"herencia"}});
if(x.testamento==="nose")add({id:"testamento-nose",area:"datos",tipo:"dato",gravedad:2,titulo:"Aún no consta si hay testamento",detalle:"El cálculo se hace como si no lo hubiera. Con testamento cambian los herederos y las cuotas.",accion:"Pide el certificado de últimas voluntades (desde 15 días hábiles tras el fallecimiento).",enlace:{tramite:"ultimas"}});
