const ries=D.items.filter((i)=>i.tipo==="riesgo"),ops=D.items.filter((i)=>i.tipo==="oportunidad"),datos=D.items.filter((i)=>i.tipo==="dato");
if(ries.length){bl.push({tipo:"p",texto:"Riesgos"});bl.push({tipo:"lista",items:ries.map(linea)});}
if(ops.length){bl.push({tipo:"p",texto:"Oportunidades"});bl.push({tipo:"lista",items:ops.map(linea)});}
if(datos.length){bl.push({tipo:"p",texto:"Datos por completar"});bl.push({tipo:"lista",items:datos.map(linea)});}
