MO_.vtPend=true;
const t=document.startViewTransition(()=>{MO_.vtPend=false;MO_.enVT=true;try{fn();}finally{MO_.enVT=false;}});
const fin=()=>{if(!MO_.vtPend)delete html.dataset.vt;};
