await sgKVBorrar("red");await sgKVBorrar("red-estado");
Object.assign(RED,{cfg:null,estado:null,raiz:null,carpeta:null,clave:null,sal:"",permiso:null,falta:"",error:"",resumen:null,presencia:[]});
